        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[200%] h-[150%] bg-[radial-gradient(ellipse_at_center,_rgba(16,185,129,0.03)_0%,rgba(255,255,255,0)_60%)] z-0 pointer-events-none"></div>

      </section>

      {selectedItem && (
        <PortfolioModal 
          isOpen={isModalOpen}
          onClose={closeModal}
          item={selectedItem}
        />
      )}
    </>
  );
};

